entries[202387] = { ["name"] = "Leicht zerzauster Zylinder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n70 ( 70)\n\"Etwas versengt, aber offensichtlich hat jemand diesen Zylinder sehr geliebt. Ein Gentleman würde sich sicher freuen, ihn zurückzubekommen.\"" }
entries[202394] = { ["name"] = "Ebenenfrischfleisch", ["text"] = "Questgegenstand\n\"Eine Sammlung von Fleischwaren aus den Ebenen von Ohn'ahra.\"" }
entries[202395] = { ["name"] = "Rumble-Folie", ["text"] = "Wird an Kriegsmeute gebunden\n\"An einem Warcraft Rumble-Spielautomat erhaltet Ihr damit einen neuen Miniaturlook!\"" }
entries[202396] = { ["name"] = "Ebenenholz", ["text"] = "Questgegenstand\n\"Das sollte helfen, die heruntergekommenen Bauwerke der Zentauren zu verstärken.\"" }
entries[202398] = { ["name"] = "Goldene Rumble-Folie", ["text"] = "Wird an Kriegsmeute gebunden\n\"An einer K.R.I.E.G.s-Maschine könnt Ihr die Miniatur zu Gold aufwerten!\"" }
entries[202399] = { ["name"] = "Ausgestopfte Puppe", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine ausgestopfte Puppe, die alle Haustiere lieben.\"" }
entries[202400] = { ["name"] = "Beruhigendes Räucherwerk", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein paar wohltuende Gerüche für zu Hause.\"" }
entries[202401] = { ["name"] = "Kaktusapfel Surprise", ["text"] = "Benutzen: Stellt im Verlauf von 18 Sek. ( 38 * 18 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 0 Ausdauer.\n\"Die Überraschung ist, wie enttäuscht Ihr seid.\"\nVerkaufspreis:" }
entries[202402] = { ["name"] = "Sack voller Kaktusäpfel", ["text"] = "Questgegenstand\n\"Beinhaltet die Träume und Hoffnungen eines jungen Abenteurers. Und Kaktusäpfel.\"" }
