entries[202667] = { ["name"] = "Versiegelte Artefaktschriftrolle", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\nBenutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n\"Eine magisch versiegelte Schriftrolle zum Fundort eines vergessenen Artefakts auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Drachenschuppenexpedition von Interesse sein.\"" }
entries[202668] = { ["name"] = "Versiegelte Geisterschriftrolle", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\nBenutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n\"Eine magisch versiegelte Schriftrolle zum Aufenthaltsort einer Geisterbestie auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Zentauren der Maruuk von Interesse sein.\"" }
entries[202669] = { ["name"] = "Versiegelte Fischschriftrolle", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\nBenutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n\"Eine magisch versiegelte Schriftrolle zu den Aufenthaltstorten seltener Fische auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Tuskarr von Iskaara von Interesse sein.\"" }
entries[202670] = { ["name"] = "Versiegelte Wissensschriftrolle", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\nBenutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n\"Eine magisch versiegelte Schriftrolle zu den Aufenthaltstorten verborgenen Wissens auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für das Valdrakkenabkommen von Interesse sein.\"" }
entries[202690] = { ["name"] = "Ziersträucher", ["text"] = "Questgegenstand\nEinzigartig\n\"Schön geformte Sträucher mit einem gewissen Extra.\"" }
entries[202691] = { ["name"] = "Henrys Handtasche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n10 Platz Reagenzientasche\nVerkaufspreis:" }
entries[202692] = { ["name"] = "Dreschflegel des Gnollunholds", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n37 - 49 Schaden Geschwindigkeit 2.60\n(16.5 Schaden pro Sekunde)\n+15 [Beweglichkeit oder Stärke]\n+22 Ausdauer\nErhöht Eure kritische Trefferwertung um + 29.\nHaltbarkeit 110 / 110\n\"Gnolle haben so kräftige Gebisse, dass sie damit die Knochen ihrer Gegner ganz einfach zermalmen können. Das hier nutzen sie nur zum Spaß.\"\nVerkaufspreis:" }
entries[202693] = { ["name"] = "Drachenfruchtküchlein", ["text"] = "Questgegenstand\n\"Mit Liebe in Flammen gebacken.\"" }
entries[202694] = { ["name"] = "Lehmige Erde", ["text"] = "Questgegenstand\n\"Angereichert mit Nährstoffen aus dem Traum.\"" }
entries[202695] = { ["name"] = "Uraltes Wasser", ["text"] = "Questgegenstand\n\"Das Wasser scheint immer eine perfekte, erfrischende Temperatur zu haben.\"" }
entries[202696] = { ["name"] = "Trostentchen", ["text"] = "Questgegenstand\n\"Ein weiches Plüschtier, das schon von vielen Jungtieren geliebt wurde.\"" }
entries[202697] = { ["name"] = "Blutrotes Kissen", ["text"] = "Questgegenstand\n\"Höchster Komfort für Welpen.\"" }
entries[202698] = { ["name"] = "Die Stimme der Drachkin 4: Macht & Recht", ["text"] = "Questgegenstand\n\"Die Drachen haben über uns geherrscht, weil sie stärker waren als wir. Aber gemeinsam, in großen Zahlen, sind wir stärker als sie. Wenn Macht einem recht gibt, sind wir im Recht, solange wir den Mut haben, uns gemeinsam aufzulehnen. - Anstifterin Belaphon\"" }
entries[202699] = { ["name"] = "Die Stimme der Drachkin 2: 100 Jahrhunderte verlassen", ["text"] = "Questgegenstand\n\"Für 100 Jahre haben sie uns alleingelassen, während wir uns um \"ihre\" Inseln gekümmert, \"ihre\" Städte und \"ihre\" Straßen beschützt und den Frieden gewahrt haben. Und für was? Nur, um 99 weitere Male so zurückgelassen zu werden. Sollen wir sie mit offenen Armen willkommen heißen und uns ihnen wie gewohnt unterwerfen? - Anstifterin Belaphon\"" }
entries[202700] = { ["name"] = "Die Stimme der Drachkin 3: 100 Jahrhunderte unabhängig", ["text"] = "Questgegenstand\n\"Die Drachen sind zurückgekehrt und erwarten von uns, wie früher zu sein, doch wir haben uns in diesen 100 Jahrhunderten geändert. Wir sind gewachsen. Wir dienen ihnen nicht länger, sind keine Leibeigenen mehr. Wir haben unseren Pfad gewählt, für 10.000 Jahre, und das werden wir wieder. - Anstifterin Belaphon\"" }
entries[202701] = { ["name"] = "Die Stimme der Drachkin 5: Der Kodex der Rebellen", ["text"] = "Questgegenstand\n\"Und so schwören wir gemeinsam auf den Kodex der Rebellen. Keine Herrscher außer uns selbst. Keine Bestimmung ohne Unabhängigkeit. Kein Schwarm außer den Schwarmlosen. - Anstifterin Belaphon\"" }
entries[202702] = { ["name"] = "Die Stimme der Drachkin 1: Der Wert der Drachkin", ["text"] = "Questgegenstand\n\"Die Drachen glauben, dass sie mehr wert sind als wir. Deswegen musste sich Sendrax für ein Drachenei opfern, das vermutlich nicht mal lebensfähig ist. Sie sagen, sie wäre eine Heldin, doch in Wahrheit ist sie eines ihrer Opfer. - Anstifterin Belaphon\"" }
entries[202703] = { ["name"] = "Vergänglicher Sand", ["text"] = "Questgegenstand\n\"Die Sandkörner verschwinden vor Euren Augen.\"" }
entries[202705] = { ["name"] = "Schneckenschleim", ["text"] = "Questgegenstand\n\"Schleim, der von Schnecken gesammelt wurde und sich perfekt für die Herstellung von Räucherwerk eignet.\"" }
entries[202706] = { ["name"] = "Zandali-Piri-Piri", ["text"] = "Questgegenstand\n\"Kleine Chilischoten aus den Dschungeln Zandalars. Extrem scharf!\"\nVerkaufspreis:" }
entries[202707] = { ["name"] = "Kokosnuss von Un'Goro", ["text"] = "Questgegenstand\n\"Außen hart, innen lecker süß. Gorillas lieben sie.\"\nVerkaufspreis:" }
entries[202708] = { ["name"] = "Kokoskrabbencurry", ["text"] = "Questgegenstand\n\"In exotischen Gewürzen und Kokosnussmilch geschmorte Krabbe.\"" }
entries[202709] = { ["name"] = "Scharfes gebratenes Talbuksteak", ["text"] = "Questgegenstand\n\"Ein Talbuksteak in Trockenmarinade, das über sengenden Flammen gegart wurde.\"" }
entries[202710] = { ["name"] = "Gegrillter Südstromlachs", ["text"] = "Questgegenstand\n\"Gewürzt und anschließend gegrillter Lachs. Wird mit Zitrone serviert.\"" }
entries[202711] = { ["name"] = "Verlorener Kompass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Hält den Kompass.\n\"Obwohl ein Fuß fest in der Mitte verankert ist, ist der Kreis vollendet, denn der andere endet, wo alles beginnt.\"\nVerkaufspreis:" }
entries[202712] = { ["name"] = "Gummifisch", ["text"] = "Benutzen: Ihr könnt die meisten Haustiere apportieren lassen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[202713] = { ["name"] = "Verstreute Vorräte", ["text"] = "Questgegenstand\n\"Ein Teil von Jeb und Tachas Expeditionsausrüstung.\"" }
entries[202714] = { ["name"] = "M.A.S.T.", ["text"] = "Questgegenstand\nBenutzen: Wird genutzt, um den verderbten Verstand von Refti zu entgiften. (2s Abklingzeit)\n\"Der \"Mehrzweck-Abfüll- und Speichertank\", kurz M.A.S.T., kann zum Abfüllen und Speichern verschiedener Arten von Energie verwendet werden und funktioniert anschließend wie eine Art Batterie.\"" }
