entries[202855] = { ["name"] = "Maldras Ring der Elementarbindung", ["text"] = "Questgegenstand\nBenutzen: Versucht, einen Drachkinrebellen gefangen zu nehmen. (8 Sek. Abklingzeit)\n\"Maldra hat diesen Ring mit dem elementaren Bindungszauber erfüllt, der im Nebligen Tal gegen sie eingesetzt wurde.\"" }
