entries[202868] = { ["name"] = "Heilersignal", ["text"] = "Questgegenstand\nBenutzen: Gibt Viridias Heilern das Signal, verletzte Dracthyr an dieser Position zu versorgen. (15 Sek. Abklingzeit)" }
entries[202869] = { ["name"] = "Sengender Schlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Durch den Körper der Kernbestie aufgeheizt. Fast schon zu heiß für die Finger!\"" }
entries[202870] = { ["name"] = "Mysteriöse Schriften", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\n\"Ein Transkript verschlüsselter Geheimnisse, die einem von Neltharion verfassten Folianten entnommen wurde. Kann bei einem Gesandten des Valdrakkenabkommens auf der Verbotenen Insel eingetauscht werden.\"" }
entries[202871] = { ["name"] = "Drakonisches Artefakt", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\n\"Ein vorsichtig verpacktes Artefakt, das zum Vermächtnis der Dracthyr gehört. Kann bei einem Gesandten der Drachenschuppenexpedition auf der Verbotenen Insel eingetauscht werden.\"" }
entries[202872] = { ["name"] = "Zeichen des Segens", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\n\"Ein Zeichen des von Ohn'ahra gewährten Glücks. Kann bei einem Gesandten der Maruukzentauren auf der Verbotenen Insel eingetauscht werden.\"" }
entries[202873] = { ["name"] = "Hängepilzzuschnitt", ["text"] = "Questgegenstand\n80 ( 80)\n\"Gibt etwas in Eurer Hand nach, während Ihr es in einer Tasche verstaut. Das wird ein hervorragender Verband.\"" }
entries[202874] = { ["name"] = "Heilgebräu", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt bei einer verletzten Dunkelkralle oder einem verletzten Obsidianwächter Gesundheit wieder her. (2 Sek. Abklingzeit)\n\"\"Für maximale Effektivität direkt die Kehle hinabschütten.\"\"" }
entries[202875] = { ["name"] = "Schneckenlasso", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Lasso nach einer Schnecke, um sie zu bändigen und ihren Schleim einzusammeln." }
entries[203012] = { ["name"] = "Viridianherzkristall", ["text"] = "Questgegenstand\n\"Fühlt sich warm an und gibt einen zarten Ton von sich.\"" }
entries[203013] = { ["name"] = "Niffenräucherwerk", ["text"] = "Questgegenstand\nBenutzen: Schnüffelt herum.\n\"Schnüffelt daran, um die Spur zu finden!\"" }
