entries[203183] = { ["name"] = "Sindragosas anhaltende Essenz", ["text"] = "Questgegenstand\n\"Ihr hört qualvolle und wutentbrannte Schreie aus dieser kleinen Essenz. Die letzten Überreste von Sindragosa befinden sich darin und schreien in der Hoffnung, von ihrem Leid befreit zu werden.\"" }
