entries[203226] = { ["name"] = "Sturmverschmolzener Salamanther", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[203228] = { ["name"] = "Wilde blaue Ferne", ["text"] = "Questgegenstand\n\"Schillernd und unfassbar blau. Diese Blumen strahlen eine Energie aus, die Euch mit Freude und Hoffnung erfüllt.\"" }
entries[203229] = { ["name"] = "Schneckenschleim", ["text"] = "Questgegenstand\n\"Riecht... eigentlich nach gar nichts. Für Euch.\"" }
