entries[203381] = { ["name"] = "Versiegelter Brief an Neltharion", ["text"] = "Questgegenstand\n\"Der Brief verströmt den Duft von Parfüm... Jahrhunderte alt... und doch merkwürdig vertraut.\"" }
entries[203382] = { ["name"] = "Augenwinkelprojektoren", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n282 Rüstung\n+257 [Beweglichkeit oder Intelligenz]\n+416 Ausdauer\nErhöht Eure Meisterschaftswertung um + 478.\n\nTüfteleisockel\nBenötigt Ingenieurskunst der Dracheninseln (1)\nVerkaufspreis:" }
entries[203383] = { ["name"] = "Notizen über die Gleichberechtigung der Drachkin", ["text"] = "Questgegenstand\nBenutzen: Lasst die Drachkin wissen, dass Gleichberechtigung kurz bevorsteht.\n\"Zeigt den Drachkin, dass Alexstrasza plant, Änderungen vorzunehmen.\"" }
entries[203385] = { ["name"] = "Flammenlichtrune", ["text"] = "Questgegenstand\n\"Das Totem verblasst, als Ihr die Rune entfernt. Sie scheinen aufeinander abgestimmt zu sein.\"" }
entries[203386] = { ["name"] = "Kiste mit Springmaiskeksen", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Kiste mit Keksen mit dem Zeichen des Gerösteten Geißbocks.\"" }
entries[203387] = { ["name"] = "Seltsam vertraute Übungswaffe", ["text"] = "Questgegenstand\n\"Ihr wart Euch sicher, sie vor einer Ewigkeit weggeworfen zu haben, als Ihr Platz in Euren Taschen schaffen wolltet. Eine zuverlässige Freundin.\"" }
entries[203388] = { ["name"] = "Dreckiges Abzeichen", ["text"] = "Questgegenstand\n\"Das Symbol ist fast vollständig verblasst, aber vielleicht ist es für die Kirin Tor von historischer Relevanz.\"" }
entries[203389] = { ["name"] = "Glänzender Stein", ["text"] = "Questgegenstand\n\"Wenn es so glänzt, muss es doch wichtig sein, oder?!\"" }
entries[203390] = { ["name"] = "Maldras Ring der Elementarbindung", ["text"] = "Questgegenstand\nBenutzen: Fesselt Anstifterin Belaphon mit Maldras Elementarmagie. Nur auf Gegner mit weniger als 50% Gesundheit anwendbar.\n\"Maldra hat diesen Ring mit dem elementaren Bindungszauber erfüllt, der im Nebligen Tal gegen sie eingesetzt wurde.\"" }
entries[203391] = { ["name"] = "Verbeulte Zwergentaschenuhr", ["text"] = "Questgegenstand\n\"Eine Gravur auf der Rückseite lautet auf den Namen \"Professor Lichenrock\".\"" }
entries[203392] = { ["name"] = "Alte Spiegelscherbe", ["text"] = "Questgegenstand\n\"Trotz allem seid es immer noch Ihr.\"" }
entries[203393] = { ["name"] = "Schwammige Lehmkappe", ["text"] = "Questgegenstand\n\"Die Poren dieses Pilzes machen ihn ideal zum Aufsaugen von Giftstoffen. Zum Guten oder Schlechten.\"" }
entries[203394] = { ["name"] = "Elementar geladene Kugel", ["text"] = "Questgegenstand\n\"Ein merkwürdiges, kugelförmiges Artefakt, das titanischen Ursprungs zu sein scheint. Doch ein Leuchten elementarer Macht dringt aus dem Inneren.\"" }
entries[203395] = { ["name"] = "Forschungsaufzeichnungen", ["text"] = "Questgegenstand\n\"Die Aufzeichnungen sind im Anbetracht ihres Alters in bemerkenswertem Zustand. Die Notizen darin werden Drachenschuppengelehrte über Jahre hinweg beschäftigen.\"\n<Zum Lesen rechtsklicken>" }
entries[203396] = { ["name"] = "Ausgestelltes Rüstungsstück", ["text"] = "Questgegenstand\n\"Sieht nach einem Entwurf der schwarzen Drachen aus, ist allerdings deutlich kleiner als erwartet. Könnte das ein frühes Beispiel von Dracthyrrüstung sein?\"" }
entries[203397] = { ["name"] = "Kirygosas Notiz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine in einer langen, dünnen Kursivschrift und blauer Tinte verfasste Notiz.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[203398] = { ["name"] = "Dämpfendes Pulver", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen der Verbotenen Insel. Nur ein fähiger Alchemist könnte herausfinden, wie man dieses Reagenz sinnvoll einsetzt.\"\nVerkaufspreis:" }
entries[203399] = { ["name"] = "Beschädigter Dreizack", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Nur ein fähiger Schmied könnte diesen Dreizack wiederherstellen.\"\nVerkaufspreis:" }
entries[203400] = { ["name"] = "Langweilige Gewürze", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Koch könnte die Aromen vielleicht doch noch rauskitzeln.\"\nVerkaufspreis:" }
entries[203401] = { ["name"] = "Trüber Kristall", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Verzauberer könnte Verwendung für diesen Edelstein finden.\"\nVerkaufspreis:" }
entries[203402] = { ["name"] = "Defekter gnomischer Sprachkasten", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Ingenieur könnte sie vielleicht reparieren.\"\nVerkaufspreis:" }
entries[203403] = { ["name"] = "Hastig geschriebene Rune", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Schreiber könnte diese Linien ausbessern und die Rune funktionsfähig machen.\"\nVerkaufspreis:" }
entries[203404] = { ["name"] = "Kristallgabel", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Juwelenschleifer könnte diese Stimmgabel zum Singen bringen.\"\nVerkaufspreis:" }
entries[203405] = { ["name"] = "Makelloser Pelz", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein begabter Lederverarbeiter könnte daraus vielleicht etwas Nützliches schaffen.\"\nVerkaufspreis:" }
entries[203406] = { ["name"] = "Zerrissener Morqutdrachen", ["text"] = "Handwerkliche Kuriositäten\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Beute von Kreaturen auf der Verbotenen Insel. Ein fähiger Schneider könnte diesen Drachen flicken.\"\nVerkaufspreis:" }
entries[203407] = { ["name"] = "Drakonisches Unterdrückungspulver", ["text"] = "Handwerkliche Kuriositäten\n\"Diese Lösung kann bestimmten Bemühungen der Primalisten auf der Verbotenen Insel entgegenwirken. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203408] = { ["name"] = "Uralter zeremonieller Dreizack", ["text"] = "Handwerkliche Kuriositäten\n\"Dieser Dreizack ist nicht für den Kampf gemacht. Er scheint ritueller Natur zu sein. Passt auf, wo Ihr in auf der Verbotenen Insel ablegt. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203409] = { ["name"] = "Beutel funkelnder Gewürze", ["text"] = "Handwerkliche Kuriositäten\n\"Die fehlende Zutat war Liebe! Das Aroma ist phänomenal. Ein wunderbarer Geschmack der Verbotenen Insel. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203410] = { ["name"] = "Leuchtendes Kristalllesezeichen", ["text"] = "Handwerkliche Kuriositäten\n\"Dieses glitzernde Lesezeichen bettelt darum, in ein gutes Buch, wie eines der Verbotenen Insel, gelegt zu werden. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203411] = { ["name"] = "Gnomischer Sprachkasten", ["text"] = "Handwerkliche Kuriositäten\n\"Wie kommt Gnomentechnologie auf die Verbotene Insel? Ihr benötigt eine Brummsäule, um sie abzuspielen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203412] = { ["name"] = "Arkane Bannrune", ["text"] = "Handwerkliche Kuriositäten\n\"Nachdem die Linien ausgebessert wurden, ist Euch klar geworden, dass diese Rune Zauberschutze, wie die auf der Verbotenen Insel, bannen soll. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203414] = { ["name"] = "Verstärktes makelloses Leder", ["text"] = "Handwerkliche Kuriositäten\n\"Diese Flicken aus verstärktem Leder werden von den Tuskarr von Morqut oft verwendet, um beschädigte Bälge der Verbotenen Insel zu reparieren. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203415] = { ["name"] = "Traditioneller Morqutdrachen", ["text"] = "Handwerkliche Kuriositäten\n\"Manche sagen, dass an Pfosten geknüpfte Tuskarrdrachen auf der Verbotenen Insel auf den Schwingen des Geistes fliegen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203416] = { ["name"] = "Inaktiver Lebensblütensamen", ["text"] = "Handwerkliche Kuriositäten\n\"Auf der Verbotenen Insel gesammelt. Örtliches Ungeziefer wird vom Duft dieser besonderen Blüte angezogen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203417] = { ["name"] = "Rasiermesserscharfer Tierknochen", ["text"] = "Handwerkliche Kuriositäten\n\"Durch Häuten von Kreaturen der Verbotenen Insel erhalten. Dieser Knochen könnte nützlich sein, um die rauen Pelze der Wildtiere der Verbotenen Insel zu schneiden. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203418] = { ["name"] = "Verstärkter Schwingungsstein", ["text"] = "Handwerkliche Kuriositäten\n\"Auf der Verbotenen Insel gesammelt. Mit diesem instabilen Stein könnte man ein grollendes Erzvorkommen auf der Insel zum Äußersten treiben. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
entries[203419] = { ["name"] = "Scheue quakende Krabbe", ["text"] = "Handwerkliche Kuriositäten\n\"Auf der Verbotenen Insel gefangen. In einer hiesigen Falle würde dieses laute kleine Tierchen einen guten Köder abgeben. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:" }
