entries[203430] = { ["name"] = "Schutz von Igira", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Reihe spezieller Feuerschutzwerkzeuge ermöglicht es dem Träger, mit einem Durchdringungstiegel zu interagieren. Die Schutze werden bei Verwendung aufgebraucht.\"" }
entries[203431] = { ["name"] = "Ensemble: Bürde der unerbittlichen Gerechtigkeit", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Bürde der unerbittlichen Gerechtigkeit." }
entries[203432] = { ["name"] = "Beutel mit würzigen Haustierhappen", ["text"] = "Questgegenstand\nEinzigartig\n\"Nur Haustiere in ausgeprägt robuster körperlicher Verfassung können diese Happen vertragen.\"" }
entries[203433] = { ["name"] = "Käserad Welpenflüsterbrie", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein leichter, buttriger Käse mit einem Hauch Nussaroma.\"" }
entries[203434] = { ["name"] = "Bodenlose Tasche voller Schmiedekunstwaren", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält fast alles, um alles damit herzustellen, wenn man die Schmiedekunst beherrscht.\"\n<Zum Öffnen rechtsklicken>" }
