entries[203439] = { ["name"] = "Bodenlose Tasche voller Juwelierskunstwaren", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält fast alles, um alles herzustellen, sofern Ihr ein Juwelier / eine Juwelierin seid.\"\n<Zum Öffnen rechtsklicken>" }
entries[203440] = { ["name"] = "Bodenlose Tasche voller Lederverarbeitungsbedarf", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält fast alles, um alles herzustellen, sofern Ihr ein Lederverarbeiter / eine Lederverarbeiterin seid.\"\n<Zum Öffnen rechtsklicken>" }
entries[203441] = { ["name"] = "Bodenlose Tasche voller Schneiderwaren", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält fast alles, um alles herzustellen, sofern Ihr ein Schneider / eine Schneiderin seid.\"\n<Zum Öffnen rechtsklicken>" }
entries[203442] = { ["name"] = "Schneckenschleim", ["text"] = "Questgegenstand\n\"Mächtiger Schleim von einer Räucherwerkschnecke. Dies ist eine Grundzutat von Niffenräucherwerk.\"" }
entries[203443] = { ["name"] = "Kiste mit Springmaiskeksen", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Kiste mit Keksen aus dem Gerösteten Geißbock.\"" }
entries[203444] = { ["name"] = "Bodenlose Tasche mit Gemischtwaren der Dracheninseln", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält viele gewöhnliche Reagenzien, die alle Berufe benötigen. Euch fehlt immer noch etwas? Fragt einen Händler!\"\n<Zum Öffnen rechtsklicken>" }
entries[203445] = { ["name"] = "Ausgestopfte Puppe", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine ausgestopfte Puppe, die alle Haustiere lieben.\"" }
entries[203446] = { ["name"] = "Beruhigendes Räucherwerk", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein paar wohltuende Gerüche für Zuhause.\"" }
entries[203447] = { ["name"] = "Bodenlose Tasche voller optionaler Güter", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält all das Zeug, das Ihr einfach nicht liegenlassen konntet.\"\n<Zum Öffnen rechtsklicken>" }
entries[203448] = { ["name"] = "Bodenlose Tasche voller Erz", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält jede Menge Erz, das begehrt wohl jedes Herz.\"\n<Zum Öffnen rechtsklicken>" }
entries[203449] = { ["name"] = "Bodenlose Tasche voller Kräuter", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält haufenweise Blumen.\"\n<Zum Öffnen rechtsklicken>" }
entries[203450] = { ["name"] = "Bodenlose Tasche voller Bälge", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält viele Bälge, auf dass man im Erfolg schwelge!\"\n<Zum Öffnen rechtsklicken>" }
entries[203451] = { ["name"] = "Ziersträucher", ["text"] = "Questgegenstand\nEinzigartig\n\"Schön geformte Sträucher mit einem gewissen Extra.\"" }
entries[203453] = { ["name"] = "Drachenknochentotem", ["text"] = "Questgegenstand\n\"Djaradinrunen wurden in den Knochen geschnitzt.\"" }
entries[203454] = { ["name"] = "Zaqaliausrüstung", ["text"] = "Questgegenstand\n\"Die Requisiten ritueller Drachentöter, für Zeremonien wie zur Kriegsführung geeignet.\"" }
entries[203455] = { ["name"] = "Drachenzahnfetisch", ["text"] = "Questgegenstand\n\"Ein ganzer Satz Zähne junger Drachen auf einer Lederschnur aufgefädelt.\"" }
entries[203456] = { ["name"] = "Obsidiangebetsperlen", ["text"] = "Questgegenstand\n\"Eine Reihe dunkler Perlen, die den Geruch von Rauch an Euren Händen zurücklassen.\"" }
entries[203457] = { ["name"] = "Vulkanisches Kräuterpäckchen", ["text"] = "Questgegenstand\n\"Die zerstoßenen Kräuter knistern leise.\"" }
entries[203458] = { ["name"] = "Schwarze Drachenschuppenroben", ["text"] = "Questgegenstand\n\"Dicke Gewänder aus zusammengenähten Schichten schwarzen Drachenleders.\"" }
entries[203459] = { ["name"] = "Totemische Ruinen", ["text"] = "Questgegenstand\n\"Zerhackte Stücke von versteinertem Holz, Eisen und Fell.\"" }
entries[203460] = { ["name"] = "Onyxsockelring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+693 Ausdauer\n\nUrzeitlicher Sockel\nUrzeitlicher Sockel\nUrzeitlicher Sockel\n\"Dieser rätselhafte, aus Elementium geschaffene Ring hat drei leere Plätze.\"\nVerkaufspreis:" }
entries[203461] = { ["name"] = "Chronologisch neu verteilte Verpflegung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt 10% Gesundheit wieder her.\n\"Hier sind die Preise nicht explodiert.\"\nVerkaufspreis:" }
entries[203463] = { ["name"] = "Atrenoshs Tagebuch", ["text"] = "Questgegenstand\n\"Dieser altgediente, in Leder gebundene Foliant enthält Tiraden über das Soldatenleben, brutale Beschreibungen von Kämpfen und Schwärmereien über Waffen.\"" }
entries[203465] = { ["name"] = "Drakonisches Artefakt", ["text"] = "Questgegenstand\n\"Ein vorsichtig verpacktes Artefakt, das zum Vermächtnis der Dracthyr gehört. Kann bei einem Gesandten der Drachenschuppenexpedition auf der Verbotenen Insel eingetauscht werden.\"" }
entries[203466] = { ["name"] = "Drachenschuppenüberschussstruhe", ["text"] = "Questgegenstand\n\"Enthält Vorräte der Dracheninseln und andere Belohnungen für Eure Unterstützung der Drachenschuppenexpedition auf der Verbotenen Insel.\"" }
entries[203469] = { ["name"] = "Verdichtete Überreste der Stürme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[203470] = { ["name"] = "Banner der Shikaar", ["text"] = "Questgegenstand\nBenutzen: Rammt ein Banner der Shikaar in alle Nokhudleichen in der Nähe. (2 Sek. Abklingzeit)" }
entries[203471] = { ["name"] = "Schmackhafte Süßigkeiten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Mjam, mjam, mjam.\"" }
entries[203473] = { ["name"] = "Geysirblume", ["text"] = "Questgegenstand\n\"Diese Einzelblüte scheint nur am Fuße der Quellen von Ohn'iri zu gedeihen.\"" }
entries[203474] = { ["name"] = "Starkes Salamantherherz", ["text"] = "Questgegenstand\n\"Dieser Salamanther hat sein Krafttraining ernst genommen.\"" }
entries[203475] = { ["name"] = "Dringende Sturmwindeinbestellung", ["text"] = "Questgegenstand\nEinzigartig\n\"Recht unauffällig mit einem einfachen, unmarkierten Wachssiegel.\"\n<Zum Lesen rechtsklicken>" }
entries[203476] = { ["name"] = "Primalistentruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Gold, Vorräte der Dracheninseln sowie eine Chance auf kosmetische Primalistenwaffen und -rüstungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[203478] = { ["name"] = "Transportable Wärmequelle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Entzündet ein Feuer, das Verbündeten in der Nähe 15 Sek. lang ' Wärme ' gewährt.\n\nKann nur während des Ereignisses \"Der Zorn des Sturms\" in der Zukunft der Primalisten eingesetzt werden.\nVerkaufspreis:" }
