entries[203597] = { ["name"] = "Drakonische Gewänder des Hierophanten", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n334 Rüstung\n+391 Intelligenz\n+1.044 Ausdauer\nErhöht Eure kritische Trefferwertung um + 191.\nErhöht Eure Tempowertung um + 477.\nHaltbarkeit 165 / 165\nKlassen: Priester\nDrakonische Garderobe des Hierophanten (0/5)\nDrakonische Griffe des Hierophanten\nDrakonische Erzgugel des Hierophanten\nDrakonische Kniehosen des Hierophanten\nDrakonische Gewänder des Hierophanten\nDrakonische Weisheit des Hierophanten\n(2) Set Disziplin: 'Machtwort: Schild' erhöht die Effektivität Eures nächsten direkten Schaden- oder Heilzaubers um 10%.\n(2) Set Heilig: Der Einsatz von 'Gebet der Besserung' verringert die Zauberzeit des nächsten Einsatzes von 'Heilung' oder 'Gebet der Heilung' um 1 Sek. und erhöht dessen Abklingzeitverringerung für das entsprechende Segenswort um 2 Sek.\n(2) Set Schatten: 'Gedankenschlag' erhöht den Schaden Eures nächsten Einsatzes von 'Verschlingende Seuche' um 12%. Bis zu 3-mal stapelbar.\n(4) Set Disziplin: 'Sühne' erhöht die Macht Eures nächsten Einsatzes von 'Machtwort: Schild' um 60% des verursachten Schadens oder 18% der hervorgerufenen Heilung.\n(4) Set Heilig: Wenn die Abklingzeit von 'Segenswort: Epiphanie' oder 'Segenswort: Heiligung' endet, wird Eure kritische Trefferchance für 6 Sek. um 10% erhöht.\n(4) Set Schatten: 'Verschlingende Seuche' erhöht Euer Tempo 8 Sek. lang um 4%.\nVerkaufspreis:" }
entries[203598] = { ["name"] = "Umschlag von Makkos Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der zerrissene, leicht feuchte Umschlag von Makkos Tagebuch enthält die immer noch intakte erste Seite. Zusätzliche Seiten können bei Gorlocs in Szar Skeleth gefunden werden.\"" }
