entries[203651] = { ["name"] = "Sazas Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n\"Sazas Dolch ist immer noch in ausgezeichnetem Zustand, obwohl er in der Leiche eines riesigen Wurms steckte.\"" }
entries[203652] = { ["name"] = "Gaunahs Allzweck-Verzierungspulver", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Gewährt Eurer hergestellten Ausrüstung eine nicht wahrnehmbare, aber garantiert echte Verbesserung.\nBenutzbar mit: Techniken der Dracheninseln für die meisten schmucklosen, epischen Ausrüstungsteile.\n\"Lässt jegliche vorherigen Verzierungen Eurer Ausrüstung garantiert alt aussehen.\"\nVerkaufspreis:" }
entries[203653] = { ["name"] = "Leerer Elementarkern", ["text"] = "Questgegenstand\n\"Der inaktive Stein kühlt rasch in Eurer Hand ab und wartet darauf, sich an neue magische Energien zu binden.\"" }
entries[203654] = { ["name"] = "Flammentotem der Zaqali", ["text"] = "Questgegenstand\n\"Strotzt vor geschmolzener Lava, die durch Risse im Stein glüht.\"" }
entries[203655] = { ["name"] = "Durchnässter Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (2)\n\"Ein nasser und schleimiger Schlüssel.\"" }
entries[203656] = { ["name"] = "Seltsames Gerät", ["text"] = "Questgegenstand\n\"Dieses Gerät sieht aus wie eine Rute mit einem Kristall an einem Ende und einem Griff am anderen Ende, um es zu halten. Es sieht alt aus, kommt Euch aber irgendwie bekannt vor, so als hättet Ihr es schon mal irgendwo gesehen. Könnte für Voraxian von Interesse sein.\"" }
entries[203657] = { ["name"] = "Toxingegenmittel", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kleine Flasche Gegenmittel, um die Auswirkungen der Gase im Unterstützungshort zu bekämpfen.\"" }
