entries[203677] = { ["name"] = "\"Halsring\" des Hüters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+234 Ausdauer\nErhöht Eure kritische Trefferwertung um + 288.\nErhöht Eure Meisterschaftswertung um + 432.\n\"Der Ring ist zu groß für eine menschliche Hand, passt allerdings gut um den Hals. Die Stellen, an denen er sich mit den Zahnrädern verhakt hat, weisen einige Kratzer auf. Vielleicht hat ein Hüter den Ring verloren, als er an der Verteidigungsmatrix gearbeitet hat?\"\nVerkaufspreis:" }
entries[203679] = { ["name"] = "Bluthuftotem der Ahnen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nVölker: Tauren , Hochbergtauren\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[203680] = { ["name"] = "Totemwurf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Stärke\nBenutzen: Baumstammwurf! (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[203681] = { ["name"] = "Stürmische Primalistentruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet ein Sturmsiegel, Vorräte der Dracheninseln und Schätze der Primalisten sowie eine Chance auf kosmetische Primalistenwaffen und -rüstungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[203682] = { ["name"] = "Verdunkelter Elementarkern", ["text"] = "Questgegenstand\n\"Zischende Stimmen kitzeln Eure Gedanken mit Halbworten und geflüsterten Geheimnissen.\"" }
entries[203683] = { ["name"] = "Schutz von Fyrakk", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Reihe spezieller Feuerschutzwerkzeuge ermöglicht es dem Träger, mit einer Durchdringungsform zu interagieren. Die Schutze werden bei Verwendung aufgebraucht.\"" }
entries[203684] = { ["name"] = "Silberne Taschenuhr", ["text"] = "Questgegenstand\nBenutzen: Startet das aktuelle Rennen sofort neu.\n\"Wenn Ihr dies benutzt, wird das Rennen erneut gestartet.\"" }
entries[203685] = { ["name"] = "Geliehener Trank der Unsichtbarkeit", ["text"] = "Questgegenstand\nBenutzen: Ein Unsichtbarkeitstrank, der Euch hilft, in der Festung Nokhudon unbemerkt zu bleiben. Funktioniert nicht bei Kriegshunden der Nokhud. (10 Sek. Abklingzeit)" }
entries[203686] = { ["name"] = "Seltsames rundes Objekt", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Der Gegenstand gibt beim Drücken leicht nach und hat drei Löcher in der Größe von Drachenklauen. Könnte für Voraxian von Interesse sein.\"" }
entries[203687] = { ["name"] = "Staubige Vase", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine staubige Vase, auf der bildhaft ein Drache anscheinend gegen einen Djaradin kämpft und auf der gerade so eine Inschrift auszumachen ist. Könnte für Voraxian von Interesse sein.\"" }
