entries[203690] = { ["name"] = "Perlmuttblasenschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Aktiviert ein uraltes Gerät.\"" }
entries[203692] = { ["name"] = "Hornsignet von Arrosh", ["text"] = "Questgegenstand\n\"Mit Spinnengift und Blut besprenkelt.\"" }
