entries[203697] = { ["name"] = "Hornsignet von Ekrati", ["text"] = "Questgegenstand\n\"Zwei Worte wurden grob in den Ring graviert: \"In Liebe Patroklosa\".\"" }
entries[203698] = { ["name"] = "Hornsignet von Kralle Hermin", ["text"] = "Questgegenstand\n\"Neben einem Stück Schreibkohle gefunden.\"" }
entries[203699] = { ["name"] = "Zerrissene Geschenkverpackung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das Geschenk im Inneren und die Verpackung waren einst neu, doch die Zeit hat ihre Spuren hinterlassen.\"\n<Zum Öffnen rechtsklicken>" }
