entries[203701] = { ["name"] = "Neltharions Geschenkmarke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\n\"Eine einlösbare Geschenkmarke. Wird vom Tüfteltronprototyp angenommen.\"" }
entries[203702] = { ["name"] = "Experimenteller Verschmelzer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 7 prismatische Fragmente mit dem experimentellen Verschmelzer, um einen neuen, unbekannten Edelstein zu erschaffen.\nVerkaufspreis:" }
entries[203703] = { ["name"] = "Prismatisches Fragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 7 prismatische Fragmente mit dem experimentellen Verschmelzer, um einen neuen, unbekannten Edelstein zu erschaffen.\nVerkaufspreis:" }
entries[203704] = { ["name"] = "Steinzersetzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 2 std. (Realzeit)\nBenutzen: Auf ärgerliche Steinhindernisse werfen, um sie vollständig aufzulösen. (10 Sek. Abklingzeit)\n\"Sowohl zur inneren als auch äußeren Anwendung.\"\nVerkaufspreis:" }
entries[203705] = { ["name"] = "Leere Obsidianphiole", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 2 std. (Realzeit)\n\"Könnte zum Aufbewahren von Flüssigkeiten verwendet werden.\"\nVerkaufspreis:" }
entries[203706] = { ["name"] = "Hurrikanszepter", ["text"] = "Questgegenstand\nBenutzen: Überlädt den anvisierten Sturmpylon und fügt ihm Schaden zu." }
entries[203707] = { ["name"] = "Wassereimer", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft einen Wassereimer, der alle Feuer innerhalb von 3 Metern um den Zielbereich löscht.\n\"Ein Eimer frischen Höhlenwassers wie ihn Niffentöpfer nutzen.\"" }
entries[203708] = { ["name"] = "Muschelpfeife", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört den größten Schleimer der Stadt oder gibt ihn wieder frei.\n\"Benutzt diese Pfeife, um den großen Schleimer zu rufen, während Ihr ihn in Glimmerogg mit Briggul trainiert.\"" }
entries[203710] = { ["name"] = "Immerflammenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\n\"Einer von mehreren Schlüsseln, die benötigt werden, um eine gesicherte Lieferung zu öffnen. Werden nur Igiras besten Schmieden anvertraut. Diese Schlüssel werden bei Verwendung aufgebraucht.\"" }
entries[203712] = { ["name"] = "Weiche Pfauendaunen", ["text"] = "Questgegenstand\n\"Das perfekte Material zum Füllen von Kopfkissen.\"" }
entries[203713] = { ["name"] = "Mysteriöse Blume", ["text"] = "Wird beim Aufheben gebunden\n\"Eine schön geschnittene Blume. Am Stängel ist eine kleine Nachricht befestigt: \"Die Legenden sind wahr.\" Ihr erinnert Euch nicht, sie aufgehoben zu haben.\"\nVerkaufspreis:" }
entries[203714] = { ["name"] = "Schutz des gesichtslosen Zornes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+487 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Verleiht einem Verbündeten für 10 Sek. 'Windender Schutz' und absorbiert bis zu 177207 Schaden. Bei Durchbrechen verschmilzt der Schutz zu 'Windender Zorn' und fügt dem letzten Gegner, der ihn getroffen hat, im Verlauf von 6 Sek. [Quellwert] Schattenflammenschaden zu. (1 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[203715] = { ["name"] = "Triefendes Gold", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 2 std. (Realzeit)\nBenutzen: Werfen, um die schleimige, goldene Flüssigkeit im Inneren freizusetzen. (10 Sek. Abklingzeit)\n\"Schön anzusehen, schwierig auszugeben.\"\nVerkaufspreis:" }
entries[203716] = { ["name"] = "Donnerndes Banner der Aspekte", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt ein Banner auf, das Eure Erfolge im Kampf gegen die Donnernden zur Schau stellt. (10 Min Abklingzeit)" }
entries[203718] = { ["name"] = "Phiole der Flammen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 2 std. (Realzeit)\nBenutzen: Werfen, um einen Bereich in magische Flammen zu hüllen. (10 Sek. Abklingzeit)\n\"Vorsichtig behandeln.\"\nVerkaufspreis:" }
entries[203720] = { ["name"] = "Heilendes Wasser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 2 std. (Realzeit)\nBenutzen: Werfen, um das heilende Wasser im Inneren freizusetzen. (10 Sek. Abklingzeit)\n\"Jahrtausendelang magisch geläutert und verzaubert.\"\nVerkaufspreis:" }
entries[203722] = { ["name"] = "Experimentelles Drachenpack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Aktiviert das Drachenpack, um Euch in der Luft vorwärts zu bewegen. Kann in den Gewölben von Zskera und auf der Verbotenen Insel verwendet werden. (30 Sek. Abklingzeit)" }
entries[203724] = { ["name"] = "Gefahrenzuschlag für Feldsanitäter", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Vorrat verschiedener Güter, der für die nicht ausreichend gewürdigte Arbeit auf dem Schlachtfeld entschädigen soll.\"\n<Zum Öffnen rechtsklicken>" }
entries[203725] = { ["name"] = "Demonstration der Stärke", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Baumstammwurf! (2 Min Abklingzeit)\n\"Zeigt, was in Euch steckt!\"" }
entries[203727] = { ["name"] = "Schimmernde Mondbestienzügel", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit ihrer Rüstung in funkelndem Silber gelten diese ergebenen Reittiere als Segen von Elune höchstselbst.\"\nPromotion" }
entries[203729] = { ["name"] = "Ominöse chromatische Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+460 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Begebt Euch mit der Macht des Drachenschwarms in Resonanz, dem Ihr Treue geschworen habt, was Euch 475 Sekundärwert gewährt. Verbündete, die einem anderen Drachenschwarm Treue geschworen haben, erhalten 50 Sekundärwert durch Eure Resonanz. Ihr könnt nur von einer einzigen Resonanz pro Schwarm profitieren.\nBenutzen: Stimmt Euch auf einen nahegelegenen Schwurstein der Drachenschwärme auf den Dracheninseln ab.\n\"Die Schönheit ihrer wirbelnden Farben straft die nachfolgenden grausamen Experimente Lügen.\"\nVerkaufspreis:" }
entries[203730] = { ["name"] = "Rustikale Winterpelzvorräte", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[203731] = { ["name"] = "Verzauberte Bandage", ["text"] = "Questgegenstand\nBenutzen: Heilt den aktuellen verwundeten Verbündeten.\n\"Magisch verstärkt zur Verwendung für jene, die die Heilkunst nicht erlernt haben.\"" }
