entries[203832] = { ["name"] = "Uralte Pläne: Heugabel des Mojowahnsinn", ["text"] = "Benutzen: Lehrt Euch, wie man eine Heugabel des Mojowahnsinns herstellt.\nBenötigt Klassische Schmiedekunst (300)\n\nHeugabel des Mojowahnsinn\nWird beim Anlegen gebunden\nZweihändig Stangenwaffe\n6 - 13 Schaden Geschwindigkeit 3.60\n(2.6 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nAnlegen: Erhöht Angriffskraft im Kampf gegen Dämonen um 1 .\nVerkaufspreis:\nBenötigt Echtsilberbarren (12), Mächtiges Mojo (4), Gewaltig viel Mojo (6), Mojowahnsinn der Gurubashi (3), Mächtiges Trollblutelixier\nOptionale Reagenzien: [] (#48)" }
entries[203833] = { ["name"] = "Uralte Pläne: Blutbote", ["text"] = "Benutzen: Lehrt Euch, wie man einen Blutboten herstellt.\nBenötigt Klassische Schmiedekunst (300)\n\nBlutbote\nWird beim Anlegen gebunden\nEinhändig Schwert\n1 - 3 Schaden Geschwindigkeit 2.60\n(0.8 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:\nBenötigt Verzauberter Thoriumbarren (18), Arkanitbarren (8), Mächtiges Trollblutelixier (2), Gewaltig viel Mojo (6), Fläschchen der obersten Macht (2), Makelloser schwarzer Diamant\nOptionale Reagenzien: [] (#48)" }
