entries[203835] = { ["name"] = "Uralte Pläne: Feurige Rache", ["text"] = "Benutzen: Lehrt Euch, wie man eine feurige Rache herstellt.\nBenötigt Klassische Schmiedekunst (300)\n\nFeurige Rache\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nEinhändig Schwert\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+1 Stärke\n+ 2 Ausweichen\n+ 1 Vielseitigkeit\nHaltbarkeit 90 / 90\nAnlegen: Fügt Eurem Nahkampfangriff 2 Punkte Feuerschaden hinzu.\nVerkaufspreis:\nBenötigt Verzauberter Thoriumbarren (32), Essenz des Feuers (30), Hervorragendes Zauberöl , Herz des Feuers (20), Makelloser schwarzer Diamant (2), Wächterstein (4)\nOptionale Reagenzien: [] (#48)" }
entries[203836] = { ["name"] = "Uralte Pläne: Kriegsklingen der Hakkari, wiedergeboren", ["text"] = "Benutzen: Lehrt Euch, wie man wiedergeborene Kriegsklingen der Hakkari herstellt.\nLegenden zufolge können diese Klingen nur am Rande des Wahnsinns von einer Seele geschmiedet werden, deren Zorn noch heißer schwelt als die sengenden Flammen des Hasses.\nBenötigt Klassische Schmiedekunst (300)\n\nKriegsklingen der Hakkari, wiedergeboren\nWird an Kriegsmeute gebunden\n\"Legenden zufolge können diese Klingen nur am Rande des Wahnsinns von einer Seele geschmiedet werden, deren Zorn noch heißer schwelt als die sengenden Flammen des Hasses.\"\nBenötigt Arkanitbarren (24), Verzauberter Thoriumbarren (30), Dunkelrune (20), Herz des Feuers (30), Gewaltiger Smaragd (2), Gewaltig viel Mojo (10), Mojowahnsinn der Gurubashi (6)" }
entries[203837] = { ["name"] = "Uralte Pläne: Schlitzer der Gurubashi", ["text"] = "Benutzen: Lehrt Euch, wie man einen Schlitzer der Gurubashi herstellt.\nBenötigt Klassische Schmiedekunst (300)\n\nSchlitzer der Gurubashi\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\nHaltbarkeit 90 / 90\nTrefferchance: Zerhäckselt den Feind für 2 Naturschaden.\nAnlegen: +10 Fertigkeit in klassischer Kürschnerei.\n\"Dient auch als Kürschnermesser.\"\nVerkaufspreis:\nBenötigt Echtsilberbarren (18), Verzauberter Thoriumbarren (6), Dunkelrune (10), Magierblutelixier (3), Makelloser schwarzer Diamant (2), Wächterstein (4)\nOptionale Reagenzien: [] (#48)" }
