entries[203995] = { ["name"] = "Winterfellumhang", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nErfordert einen wohlwollenden Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[203996] = { ["name"] = "Feuriger Flussstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 [Beweglichkeit oder Intelligenz]\nAnlegen: Schwimmt mit dem Strom, der alle 30 Sek. zu Hochwasser ansteigt oder zu Niedrigwasser absinkt.\n\nBei Niedrigwasser gewährt Euch Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit 12 Sek. lang 1201 kritischen Trefferwert.\n\nBei Hochwasser löst Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit eine Lavawelle aus, die über Eurem Ziel bricht und 52168 Vulkanschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Dieser Schaden ist verringert, wenn die Lavawelle weniger als 20 Meter weit reicht.\nVerkaufspreis:" }
entries[203997] = { ["name"] = "Unbehandelte Riesenwildschafflanke", ["text"] = "Questgegenstand\nEinzigartig\n\"Mageres, vielseitiges Protein. Hält sich nach dem Räuchern einen Mond lang.\"" }
entries[203998] = { ["name"] = "Käfersaft", ["text"] = "Questgegenstand\nEinzigartig\n\"Merkwürdig und ungewöhnlich.\"" }
entries[204000] = { ["name"] = "Sturmerfüllter Stein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Wird einem Gegner ein kritischer Treffer zugefügt, besteht die Chance, dass er und 2 Gegner in der Nähe geschockt werden und Naturschaden 10234 erleiden.\nVerkaufspreis:" }
entries[204001] = { ["name"] = "Widerhallender Donnerstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Bewegung baut eine elektrische Ladung auf, wodurch Eure nächste Schadensfähigkeit außerdem 13238 Naturschaden verursacht.\nVerkaufspreis:" }
entries[204002] = { ["name"] = "Feuergeküsster Stein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Verursachen von Schaden besteht eine Chance, dass der Gegner in Brand gesteckt wird und ( 2271 * 7) Feuerschaden im Verlauf von 7 Sek. erleidet.\nVerkaufspreis:" }
entries[204003] = { ["name"] = "Tobender Magmastein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Absorbieren von Schaden besteht eine Chance, dass Ihr mit Lava umhüllt werdet, sodass Nahkampfangreifer 6 Sek. lang 2207 Feuerschaden erleiden.\nVerkaufspreis:" }
entries[204004] = { ["name"] = "Sengender Rauchstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Bei erfolgreichen Unterbrechungen wird Rauch freigesetzt und fügt Gegnern innerhalb eines kegelförmigen Bereichs von 8 Metern vor Euch 7566 Feuerschaden zu.\nVerkaufspreis:" }
entries[204005] = { ["name"] = "Entropischer Teufelsstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Der durch urzeitliche Steine verursachte Feuerschaden wird um 60% erhöht und zu Chaosschaden.\nVerkaufspreis:" }
entries[204006] = { ["name"] = "Unbeugsamer Erdstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Erleiden von Feuerschaden besteht die Chance, dass Ihr Euch in einen Schild hüllt und 12 Sek. lang 49677 Schaden absorbiert.\nVerkaufspreis:" }
entries[204007] = { ["name"] = "Glänzender Obsidianstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Erhalten eines Absorptionsschild durch einen urzeitlichen Stein bricht der Boden auf und verursacht 23641 körperlichen Schaden, der auf Gegner innerhalb von 5 Metern aufgeteilt wird.\n\nDer Schaden wird für jeden getroffenen Gegner erhöht, bis zu 5 Gegner.\nVerkaufspreis:" }
entries[204009] = { ["name"] = "Schimmernder Eisenstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Wenn Ihr Euch im Kampf 3 Sek. lang nicht bewegt, wächst Eure Entschlossenheit, was 24839 Schaden absorbiert und den Schaden Eurer automatischen Angriffe 25 Sek. Sek. lang um 434 erhöht.\nVerkaufspreis:" }
entries[204010] = { ["name"] = "Überschwemmender Wasserstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Fähigkeiten haben eine Chance, einen Verbündeten in der Nähe zu durchnässen, was ihn im Verlauf von 6 Sek. um ( 6625 * 6) Gesundheit heilt.\nVerkaufspreis:" }
entries[204011] = { ["name"] = "Gefrierender Eisstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Verursachen von Schaden besteht eine Chance, den Gegner zu unterkühlen, was ihm 14828 Frostschaden zufügt und ihn für 6 Sek. um 15% verlangsamt.\nVerkaufspreis:" }
entries[204012] = { ["name"] = "Kalter Froststein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Gewährt alle 20 Sek. einen Frostschild, der 33118 Schaden absorbiert und Nahkampfangreifer für 5 Sek. um 15% verlangsamt.\nVerkaufspreis:" }
entries[204013] = { ["name"] = "Kondensierender Dampfstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Erhalten von Heilung besteht eine Chance, Dampf freizusetzen, der bei Euch sowie 2 Verbündeten in der Nähe 16428 Gesundheit wiederherstellt.\nVerkaufspreis:" }
entries[204014] = { ["name"] = "Funkelnder Manastein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Frosteffekte durch urzeitliche Steine stellen im Verlauf von 3 Sek. insgesamt ( 332 * 3) Mana wieder her.\nVerkaufspreis:" }
entries[204015] = { ["name"] = "Wirbelnder Mojostein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: In der Nähe einer sterbenden Kreatur wird ihr ein Teil ihres Mojo entzogen und letztendlich kristallisiert.\nVerkaufspreis:" }
entries[204018] = { ["name"] = "Summender Arkanstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Verursachen von Magieschaden besteht eine Chance, für jede ausgerüstete Art urzeitlicher Steine arkane Geschosse abzufeuern, die jeweils 6896 Arkanschaden verursachen.\nVerkaufspreis:" }
entries[204019] = { ["name"] = "Harmonischer Musikstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Erhöht bei Kampfbeginn Eure tertiären Werte und die von 4 Verbündeten in der Nähe 8 Sek. lang um 364 .\nVerkaufspreis:" }
entries[204020] = { ["name"] = "Wilder Geisterstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Natur- und Heileffekte durch urzeitliche Steine stellen bei 5 Verbündeten in der Nähe im Verlauf von 7 Sek. ( 1174 * 7) Gesundheit wieder her.\nVerkaufspreis:" }
entries[204021] = { ["name"] = "Nekromantischer Todesstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Einmal pro Minute gewährt Bewegung in der Nähe einer Leiche 25 Sek. Sek. lang die Ausrüstungseffekte der begehrlichen Blut-, kalten Frost- und pestilenten Seuchensteine.\n\nIst einer dieser Effekte bereits aktiv, erhöht sich seine Wirksamkeit um 75%.\nVerkaufspreis:" }
entries[204022] = { ["name"] = "Pestilenter Seuchenstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Verursachen von Schaden kann das Ziel mit einer Seuche infiziert werden, die sich zu nahen Gegnern ausbreitet und im Verlauf von 9 Sek. ( 982 * 9) Naturschaden verursacht.\nVerkaufspreis:" }
entries[204025] = { ["name"] = "Unergründlicher Pastellstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Bei Zaubern und Fähigkeiten besteht eine Chance, einen zufälligen Effekt eines urzeitlichen Steins auszulösen.\nVerkaufspreis:" }
entries[204027] = { ["name"] = "Begehrlicher Blutstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Beim Verursachen von Schaden besteht eine Chance, Leben zu entziehen, was 11768 Schattenschaden verursacht und Euch in Höhe des verursachten Schadens heilt.\nVerkaufspreis:" }
entries[204029] = { ["name"] = "Prophetischer Zwielichtstein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Schadenseffekte Eurer urzeitlichen Steine lösen einen Eurer Heileffekte aus und umgekehrt.\nVerkaufspreis:" }
entries[204030] = { ["name"] = "Windgeformter Stein", ["text"] = "Urzeitlicher Stein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nAnlegen: Bewegung holt den Wind auf Eure Seite und gewährt Euch 94 Geschwindigkeit. Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[204063] = { ["name"] = "Windsors Tagebuch", ["text"] = "Questgegenstand\n\"Eines von vielen. Enthält nützliche Informationen über Onyxia und ihre Pläne in Sturmwind, wurde aber von hungrigen Wölfen als Kauspielzeug missbraucht und sieht entsprechend aus.\"\n<Zum Lesen rechtsklicken>" }
