entries[204164] = { ["name"] = "Medaillon des Obsidiankämpfers", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+205 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[204165] = { ["name"] = "Inbrunstinsigne des Obsidiankämpfers", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 291.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 457 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
